trait SpecArrayClone: Clone {
    fn clone<const N: usize>(array: &[Self; N]) -> [Self; N];
}

impl<T: Clone> SpecArrayClone for T {
    #[inline]
    default fn clone<const N: usize>(array: &[T; N]) -> [T; N] {
        let mut ptr: *const T = array.as_ptr();
        // SAFETY: Unless a panic occurs, from_fn will call the closure N times,
        // so our pointer arithmetic will be in bounds for the N-element array.
        // This works even for ZSTs, since in that case, add() is a no-op.
        from_fn(move |_| unsafe {
            let old = ptr;
            ptr = ptr.add(1);
            (&*old).clone()
        })
    }
}

impl<T: TrivialClone> SpecArrayClone for T {
    #[inline]
    fn clone<const N: usize>(array: &[T; N]) -> [T; N] {
        // SAFETY: `TrivialClone` implies that this is equivalent to calling
        // `Clone` on every element.
        unsafe { ptr::read(array) }
    }

pub fn try_reserve_exact(&mut self, additional: usize) -> Result<(), TryReserveError> {
    self.buf.try_reserve_exact(self.len, additional)
}

pub fn resize(&mut self, new_len: usize, value: T) {
    let len = self.len();

    if new_len > len {
        self.extend_with(new_len - len, value)
    } else {
        self.truncate(new_len);
    }
}

fn extend_with(&mut self, n: usize, value: T) {
    self.reserve(n);

    unsafe {
        let mut ptr = self.as_mut_ptr().add(self.len());
        // Use SetLenOnDrop to work around bug where compiler
        // might not realize the store through `ptr` through self.set_len()
        // don't alias.
        let mut local_len = SetLenOnDrop::new(&mut self.len);

        // Write all elements except the last one
        for _ in 1..n {
            ptr::write(ptr, value.clone());
            ptr = ptr.add(1);
            // Increment the length in every step in case clone() panics
            local_len.increment_len(1);
        }

        if n > 0 {
            // We can write the last element directly without cloning needlessly
            ptr::write(ptr, value);
            local_len.increment_len(1);
        }

        // len set by scope guard
    }
}

unsafe fn try_reserve_exact(
    &mut self,
    len: usize,
    additional: usize,
    elem_layout: Layout,
) -> Result<(), TryReserveError> {
    if self.needs_to_grow(len, additional, elem_layout) {
        // SAFETY: Precondition passed to caller
        unsafe {
            self.grow_exact(len, additional, elem_layout)?;
        }
    }
    unsafe {
        // Inform the optimizer that the reservation has succeeded or wasn't needed
        hint::assert_unchecked(!self.needs_to_grow(len, additional, elem_layout));
    }
    Ok(())
}

const unsafe fn set_ptr_and_cap(&mut self, ptr: NonNull<[u8]>, cap: usize) {
    // Allocators currently return a `NonNull<[u8]>` whose length matches
    // the size requested. If that ever changes, the capacity here should
    // change to `ptr.len() / size_of::<T>()`.
    self.ptr = Unique::from(ptr.cast());
    self.cap = unsafe { Cap::new_unchecked(cap) };
}

/// # Safety
/// - `elem_layout` must be valid for `self`, i.e. it must be the same `elem_layout` used to
///   initially construct `self`
/// - `elem_layout`'s size must be a multiple of its alignment
/// - The sum of `len` and `additional` must be greater than the current capacity
unsafe fn grow_exact(
    &mut self,
    len: usize,
    additional: usize,
    elem_layout: Layout,
) -> Result<(), TryReserveError> {
    if elem_layout.size() == 0 {
        // Since we return a capacity of `usize::MAX` when the type size is
        // 0, getting to here necessarily means the `RawVec` is overfull.
        return Err(CapacityOverflow.into());
    }

    let cap = len.checked_add(additional).ok_or(CapacityOverflow)?;

    // SAFETY: preconditions passed to caller
    let ptr = unsafe { self.finish_grow(cap, elem_layout)? };

    // SAFETY: `finish_grow` would have failed if `cap > isize::MAX`
    unsafe { self.set_ptr_and_cap(ptr, cap) };
    Ok(())
}

unsafe fn finish_grow(
    &self,
    cap: usize,
    elem_layout: Layout,
) -> Result<NonNull<[u8]>, TryReserveError> {
    let new_layout = layout_array(cap, elem_layout)?;

    let memory = if let Some((ptr, old_layout)) = unsafe { self.current_memory(elem_layout) } {
        // FIXME(const-hack): switch to `debug_assert_eq`
        debug_assert!(old_layout.align() == new_layout.align());
        unsafe {
            // The allocator checks for alignment equality
            hint::assert_unchecked(old_layout.align() == new_layout.align());
            self.alloc.grow(ptr, old_layout, new_layout)
        }
    } else {
        self.alloc.allocate(new_layout)
    };

    // FIXME(const-hack): switch back to `map_err`
    match memory {
        Ok(memory) => Ok(memory),
        Err(_) => Err(AllocError { layout: new_layout, non_exhaustive: () }.into()),
    }
}
